def decode_native_text(
    raw: bytes,
    *,
    japanese: bool = False,
    require_terminator: bool = False,
    line_break: str = " | ",
    line_breaks: Mapping[int, str] | None = None,
) -> str:
    """Decode actual expanded text, not unresolved placeholder templates.

    FC15/16 change the game's language mode. F9 glyphs use the source names
    when Unicode has no unambiguous matching game glyph. Unknown/truncated
    bytes raise with position and bounded input evidence; '?' is only the
    literal native question-mark glyph AC.
    """
    out: list[str] = []
    index = 0
    while index < len(raw):
        byte = raw[index]
        if byte == 0xFF:
            return "".join(out)
        if byte in (0xFA, 0xFB, 0xFE):
            out.append(line_breaks.get(byte, line_break) if line_breaks is not None else line_break)
            index += 1
            continue
        if byte == 0xFC:
            if index + 1 >= len(raw) or raw[index + 1] not in CONTROL_ARGS:
                raise ValueError(
                    f"unknown/truncated text control at byte {index}: {raw[:64].hex()}"
                )
            control = raw[index + 1]
            count = CONTROL_ARGS[control]
            if index + 2 + count > len(raw):
                raise ValueError(
                    f"truncated text control arguments at byte {index}: {raw[:64].hex()}"
                )
            if control == 21:
                japanese = True
            elif control == 22:
                japanese = False
            elif control == 12:
                glyph = raw[index + 2]
                # Renderer ORs escaped glyph with 0x100, identical to F9.
                table = SPECIAL_GLYPHS
                if glyph not in table:
                    raise ValueError(
                        f"unknown escaped text glyph at byte {index}: {raw[:64].hex()}"
                    )
                out.append(table[glyph])
            index += 2 + count
            continue
        if byte == 0xF9:
            if index + 1 >= len(raw) or raw[index + 1] not in SPECIAL_GLYPHS:
                raise ValueError(
                    f"unknown/truncated special glyph at byte {index}: {raw[:64].hex()}"
                )
            out.append(SPECIAL_GLYPHS[raw[index + 1]])
            index += 2
            continue
        table = JAPANESE_GLYPHS if japanese else ENGLISH_GLYPHS
        if byte not in table:
            raise ValueError(f"unknown text glyph 0x{byte:02X} at byte {index}: {raw[:64].hex()}")
        out.append(table[byte])
        index += 1
    if require_terminator:
        raise ValueError(f"unterminated native text: {raw[:64].hex()}")
    return "".join(out)


def native_text_payload(raw: bytes) -> bytes:
    """Return a validated expanded English-field message up to its actual EOS.

    The source decoder validates glyphs, control arities and termination first.
    Control arguments may contain FF; they are part of the identity, not EOS.
    """
    decode_native_text(raw, require_terminator=True)
    index = 0
    while raw[index] != 0xFF:
        if raw[index] == 0xFC:
            index += 2 + CONTROL_ARGS[raw[index + 1]]
        else:
            index += 2 if raw[index] == 0xF9 else 1
    return raw[:index]
